; Saltwind Docks, Questeria's harbour, where you come in off the ship. The quay street along the top with its
; warehouses, the boardwalk, and the harbour, with the ship tied up along the boardwalk and a jetty
; at either end. The city's up the street to the east. Lit, and no fog.

[map]
id = docks
name = Saltwind Docks
world = 80 190
tileset = questeria
size = 56 36
dark = no
fog = no
music = Exploring

[legend]
: = cobble
, = grass
+ = planks
~ = water

