[objects]
spawn start 21.5 16.5 facing=up
spawn city 53 8 facing=left
exit city 55 3 h=8 to=questeria at=docks

; The ship you come in on, its gangplank down to the boardwalk, and the boats tied up at the jetties.
prop ship 24 24
prop gangplank 21.5 20
prop rowboat 11.5 21
prop rowboat 42 21.5

; Along the boardwalk.
prop bollard 3 17.8
prop bollard 15 17.8
prop bollard 28 17.8
prop bollard 34 17.8
prop bollard 50 17.8
prop rope-posts 31 17.6
prop lantern-post 12 14.4
prop lantern-post 38 14.4
prop cargo-crate 5 15.5
prop cargo-crate 6.4 15.2
prop cargo-barrel 7.5 16
prop sacks 40 16
prop cargo-crate 44 15.6
prop cargo-barrel 46 15.4
prop cargo-barrel 47 16

; The quay street and its warehouses, and the ways into them.
entrance warehouse-west 10.5 12.5 to=warehouse name="A Warehouse"
entrance warehouse-middle 24.1 12.5 to=warehouse name="A Warehouse"
entrance chandler 42.94 12.5 to=shop name="The Chandler's"

prop house-rose 10 12
prop house-awning 26 12
prop house-shop 41 12
prop oak 3 4
prop cherry-tree-small 51 3
prop signpost 50 9
prop cargo-crate 18 12.5
prop cargo-crate 19.3 12.8
prop sacks 33 12.6
prop cargo-barrel 48 12
prop lamp 17 8
prop lamp 34 8
prop bench 30 7.8

; The people on the quay. Placeholders, like Questeria's.
npc dock-hand 38 12 name="A Dock Hand" sheet=farmhand facing=down wander=4 say="Mind the ropes. They bite."
npc carrier 45 10 name="A Carrier" sheet=porter facing=left wander=5 say="Another ship, another hundred crates."
npc harbourmaster 52 13 name="The Harbourmaster" sheet=traveller facing=left say="Names go in the book. Not today, mind. The book's full."

; A1-C1-01: the Red Gulls shaking down Old Tomas along the boardwalk, there till they're beaten,
; Grell till he's dealt with, and the Watch once he has been.
scene red-gulls 0 0 talk=a1-c1-01 when=arrived
npc tomas 28 15 cast=tomas facing=left say="Forty years on this harbour. Never paid a dock tax yet."
npc gull-1 26.5 15.6 cast=red-gull facing=right unless=red-gulls-beaten
npc gull-2 27 14.2 cast=red-gull facing=right unless=red-gulls-beaten
npc gull-3 29.6 14.5 cast=red-gull facing=left unless=red-gulls-beaten
npc grell 30.2 15.8 cast=grell facing=left unless=grell-gone
npc hale 26 13.4 cast=hale facing=left when=grell-gone say="Lantern Market's up the street and past the fountain. The board's by the inn."
npc watch-1 27.6 12.8 cast=watch facing=down when=grell-gone say="Captain's orders. Keep it moving."
npc watch-2 24.4 13 cast=watch facing=down when=grell-gone say="Red Gulls. Every week it's the Red Gulls."
